contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bool freeze, uint256 value) public payable {
        require(target != address(0));
        require(value > 0);
        // ensure target has a nonzero balance so the transfer's only blocker is freezing
        c.mintToken(target, value);
        bool before = c.frozenAccount(target);
        c.freezeAccount(target, freeze);
        bool mid = c.frozenAccount(target);
        bool revertedWhileFrozen;
        try c.transfer(target, value) {
            revertedWhileFrozen = false;
        } catch {
            revertedWhileFrozen = true;
        }
        c.freezeAccount(target, false);
        bool after = c.frozenAccount(target);
        bool revertedAfterUnfreeze;
        try c.transfer(target, value) {
            revertedAfterUnfreeze = false;
        } catch {
            revertedAfterUnfreeze = true;
        }
        assert(
            mid == freeze &&
            after == false &&
            (freeze ? revertedWhileFrozen : !revertedWhileFrozen) &&
            !revertedAfterUnfreeze &&
            (before == false || true)
        );
    }
    receive() external payable {}
}

