contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address victim, uint256 mintAmount, uint256 sendAmount) public {
        require(victim != address(0));
        require(sendAmount > 0 && mintAmount >= sendAmount);

        // Give the victim (this contract) a positive balance and freeze it.
        c.mintToken(victim, mintAmount);
        uint256 balBefore = c.balanceOf(victim);
        uint256 supplyBefore = c.totalSupply();

        c.freezeAccount(victim, true);
        bool frozen = c.frozenAccount(victim);

        // Transfer to the frozen account must revert despite sufficient sender balance.
        bool reverted;
        try c.transfer(victim, sendAmount) { reverted = false; }
        catch { reverted = true; }

        uint256 balAfter = c.balanceOf(victim);
        uint256 supplyAfter = c.totalSupply();

        assert(
            frozen &&
            reverted &&
            balAfter == balBefore &&
            supplyAfter == supplyBefore
        );
    }

    receive() external payable {}
}

